+static bool isSameOrChildProcess(qint64 pid, qint64 ancestorPid)
+{
+    // Applications often play audio from a helper process (browsers, terminals running a player…)
+    for (int depth = 0; pid > 1 && depth < 16; ++depth) {
+        if (pid == ancestorPid) {
+            return true;
+        }
+        QFile stat(u"/proc/%1/stat"_s.arg(pid));
+        if (!stat.open(QIODevice::ReadOnly)) {
+            return false;
+        }
+        const QByteArray data = stat.readAll();
+        // The process name can contain spaces and parentheses, the parent PID is the second field after it
+        const QList<QByteArray> fields = data.mid(data.lastIndexOf(')') + 2).split(' ');
+        if (fields.size() < 2) {
+            return false;
+        }
+        pid = fields.at(1).toLongLong();
+    }
+    return false;
+}
