+AudioShortcutsService::ActiveApplication AudioShortcutsService::activeApplication() const
+{
+    ActiveApplication application;
+
+    QModelIndex activeTask;
+    for (int i = 0; i < m_windowTasksModel->rowCount(); ++i) {
+        const QModelIndex index = m_windowTasksModel->index(i, 0);
+        if (index.data(TaskManager::AbstractTasksModel::IsActive).toBool()) {
+            activeTask = index;
+            break;
+        }
+    }
+    if (!activeTask.isValid()) {
+        return application;
+    }
+
+    const qint64 pid = activeTask.data(TaskManager::AbstractTasksModel::AppPid).toLongLong();
+    const QString appId = activeTask.data(TaskManager::AbstractTasksModel::AppId).toString();
+    application.name = activeTask.data(TaskManager::AbstractTasksModel::AppName).toString();
+    application.iconName = activeTask.data(Qt::DecorationRole).value<QIcon>().name();
+
+    const auto sinkInputs = PulseAudioQt::Context::instance()->sinkInputs();
+    for (PulseAudioQt::SinkInput *sinkInput : sinkInputs) {
+        const QVariantMap properties = sinkInput->properties();
+        const qint64 streamPid = properties.value(u"application.process.id"_s).toLongLong();
+        const QString portalAppId = properties.value(u"pipewire.access.portal.app_id"_s).toString();
+        if ((pid > 0 && isSameOrChildProcess(streamPid, pid)) || (!appId.isEmpty() && portalAppId == appId)) {
+            application.streams.append(sinkInput);
+        }
+    }
+
+    if (!application.streams.isEmpty()) {
+        if (application.name.isEmpty()) {
+            application.name = application.streams.constFirst()->name();
+        }
+        if (application.iconName.isEmpty()) {
+            application.iconName = application.streams.constFirst()->iconName();
+        }
+    }
+    if (application.iconName.isEmpty()) {
+        application.iconName = u"audio-volume-high"_s;
+    }
+
+    return application;
+}
+
+void AudioShortcutsService::changeActiveApplicationVolume(int deltaPercent)
+{
+    const ActiveApplication application = activeApplication();
+    if (application.streams.isEmpty()) {
+        showActiveApplicationNotPlaying(application);
+        return;
+    }
+
+    int percent = 0;
+    for (PulseAudioQt::SinkInput *sinkInput : application.streams) {
+        percent = changeVolumePercent(sinkInput, deltaPercent);
+    }
+    if (m_globalConfig->volumeOsd()) {
+        m_osdDBusInterface->mediaPlayerVolumeChanged(percent, application.name, application.iconName);
+    }
+}
+
+void AudioShortcutsService::toggleActiveApplicationMute()
+{
+    const ActiveApplication application = activeApplication();
+    if (application.streams.isEmpty()) {
+        showActiveApplicationNotPlaying(application);
+        return;
+    }
+
+    const bool mute = std::any_of(application.streams.cbegin(), application.streams.cend(), [](PulseAudioQt::SinkInput *sinkInput) {
+        return !sinkInput->isMuted();
+    });
+    for (PulseAudioQt::SinkInput *sinkInput : application.streams) {
+        sinkInput->setMuted(mute);
+    }
+    if (m_globalConfig->muteOsd()) {
+        const int percent = mute ? 0 : volumePercent(application.streams.constFirst()->volume());
+        m_osdDBusInterface->mediaPlayerVolumeChanged(percent, application.name, application.iconName);
+    }
+}
+
+void AudioShortcutsService::showActiveApplicationNotPlaying(const ActiveApplication &application)
+{
+    if (application.name.isEmpty() || !m_globalConfig->volumeOsd()) {
+        return;
+    }
+    m_osdDBusInterface->showText(application.iconName, i18nc("@info:status OSD, %1 is an application name", "%1 is not playing audio", application.name));
+}
